const nbrs = (q, r) => DIRS.map(([a, b]) => key(q + a, r + b)).filter(k => TM[k]);
D.vision = () => { const s = S(); return 1 + (s.b.obs || 0) + (D.hasRelic('bussola') ? 1 : 0); };
D.visible = () => { const own = D.owned(), v = D.vision(), set = new Set(own); own.forEach(k => { const [q, r] = parseK(k); TILES.forEach(t => { const dq = t.q - q, dr = t.r - r; if ((Math.abs(dq) + Math.abs(dr) + Math.abs(dq + dr)) / 2 <= v) set.add(t.k); }); }); (S().revealed || []).forEach(k => set.add(k)); return set; };
D.tileDiff = t => t.ring * 12 + (t.type === 'forte' ? 16 : 0) + (t.type === 'ruina' ? 4 : 0) + (t.type === 'farol' ? 10 : 0);
D.power = p => D.lv(p) * 4 + (S().b.forja || 0) * 3 + (D.hasRelic('espada') ? 3 : 0) + (S().sk.cor3 ? 6 : 0) + 6;
D.conqChance = t => { const p = t.sec === 'cap' ? 'cor' : t.sec; return U.clamp(.5 + (D.power(p) - D.tileDiff(t)) / 40, .1, .95); };
