D.bCost = (id, lvl) => { const p = BL[id][0], m = S().sk.for5 ? .85 : 1, c = {}; if (p === 'for') { c.ouro = Math.round(60 * lvl * lvl * m); c.saber = Math.round(15 * lvl * lvl * m); } else { c[P[p].res] = Math.round(35 * lvl * lvl * m); c.ouro = Math.round(25 * lvl * lvl * m); } return c; };
