D.fxActive = () => (S().ev.fx || []).filter(f => !f.until || f.until >= today());
D.fxSum = k => D.fxActive().reduce((a, f) => a + (f.mod && f.mod[k] || 0), 0);
D.mult = res => { const s = S(); let m = 1; const bm = { saber: 'bib', vigor: 'pista', prest: 'forum' }; if (bm[res]) m += .12 * (s.b[bm[res]] || 0);
  if (res === 'saber' && D.hasRelic('abaco')) m += .15; if (res === 'ouro' && D.hasRelic('razao')) m += .1; if (res === 'prest' && D.hasRelic('selo')) m += .12; if (D.hasRelic('tocha')) m += .1;
  if (res === 'saber' && s.sk.int1) m += .15; if (res === 'ouro' && s.rank >= 6) m += .1; if (D.secretStage() >= 10) m += .1;
  const dec = D.decree(); if (dec && dec.m[res]) m += dec.m[res] * (1 + .5 * (s.b.senado || 0));
  m += D.fxSum(res); return Math.max(0, m); };

