D.weekly = () => { const s = S(), w = U.monday(today()); if (!s.wm || s.wm.wk !== w) { const r = rng('wm' + w), pool = WT.slice(), pick = []; while (pick.length < 4) { const c = pool.splice(Math.floor(r() * pool.length), 1)[0]; if (c.p === 'game' && pick.some(id => WT.find(z => z.id === id).p === 'game')) continue; pick.push(c.id); } s.wm = { wk: w, ids: pick, claimed: [], bonus: false }; } return s.wm.ids.map(id => WT.find(x => x.id === id)); };
const PM = [['cid', 'Erguer a Cidadela', [['Biblioteca nível 1', s => (s.b.bib || 0) >= 1], ['Biblioteca nível 2', s => (s.b.bib || 0) >= 2], ['Academia nível 1', s => (s.b.aca || 0) >= 1]]], ['imp', 'Império', [['5 territórios', () => D.owned().length >= 5], ['15 territórios', () => D.owned().length >= 15], ['30 territórios', () => D.owned().length >= 30]]], ['col', 'Colecionador', [['2 relíquias', s => s.relics.length >= 2], ['4 relíquias', s => s.relics.length >= 4], ['7 relíquias', s => s.relics.length >= 7]]], ['cro', 'Cronista', [['7 tributos', s => s.st.tributes >= 7], ['30 tributos', s => s.st.tributes >= 30], ['90 tributos', s => s.st.tributes >= 90]]], ['alg', 'Algoz', [['1 chefe', s => s.st.bosses >= 1], ['3 chefes', s => s.st.bosses >= 3], ['8 chefes', s => s.st.bosses >= 8]]], ['leg', 'Legado', [['1 marco', () => legacyCount() >= 3], ['5 marcos', () => legacyCount() >= 7], ['15 marcos', () => legacyCount() >= 17]]]];
