const PH = { exam: ['Negação', 'Pressão', 'Dia D'], goal: ['Inércia', 'Resistência', 'Última Muralha'], project: ['Caos', 'Execução', 'Entrega'], custom: ['Sombra', 'Cerco', 'Coração'] };
D.bossReal = b => { if (b.kind === 'exam') { const since = b.created, sk = S().sk.int3 ? 1.25 : 1; const ses = OS.all('sessions').filter(s => s.subject === b.subject && s.date >= since); const revs = OS.all('reviews').filter(r => r.subject === b.subject && [r.r1At, r.r2At, r.r3At].some(x => x && x >= since)).length; return Math.round((U.sum(ses, s => U.num(s.minutes) * (s.type === 'Simulado' ? 1.5 : 1)) + revs * 10) * sk); }
  if (b.kind === 'goal') { const g = OS.get('goals', b.ref); return g ? Math.round(OS.Goal.info(g).p * b.max) : 0; }
  if (b.kind === 'project') { const p = OS.get('projects', b.ref); return p ? Math.round(OS.Proj.info(p).prog * b.max) : 0; }
  return Math.round((b.checks || []).length * .12 * b.max); };
D.bossHP = b => Math.max(0, b.max - D.bossReal(b) - (b.game || 0));
D.bossPhase = b => { const f = D.bossHP(b) / b.max; return f > .66 ? 0 : f > .33 ? 1 : 2; };
D.suggest = () => { const s = S(), used = new Set(s.bosses.filter(b => b.status === 'active').map(b => b.ref)), t = today(), out = [];
  OS.all('assessments').filter(a => a.date >= t && U.diff(a.date, t) <= 45 && a.prep !== 'Feito' && !used.has(a.id)).forEach(a => out.push({ kind: 'exam', ref: a.id, subject: a.subject, name: a.type + ': ' + a.title, due: a.date, max: 300 + (U.num(a.weight) || 20) * 10, pillar: 'int', why: (OS.get('subjects', a.subject) || {}).name + ' · ' + U.rel(a.date) }));
  OS.all('goals').filter(g => g.status === 'Ativa' && g.due && g.due >= t && !used.has(g.id) && OS.Goal.info(g).p < 1).forEach(g => out.push({ kind: 'goal', ref: g.id, name: g.title, due: g.due, max: 600, pillar: { 'Finanças': 'for', 'Estudos': 'int', 'Academia': 'cor', 'Corrida': 'cor', 'Trabalho': 'inf', 'Empresa': 'for' }[g.cat] || 'inf', why: 'Meta · prazo ' + U.fmtD(g.due) }));
  OS.all('projects').filter(p => p.status === 'Em andamento' && p.due && p.due >= t && !used.has(p.id)).forEach(p => out.push({ kind: 'project', ref: p.id, name: p.name, due: p.due, max: 400 + OS.Proj.info(p).open.length * 25, pillar: { 'Acadêmico': 'int', 'Financeiro': 'for', 'Empresarial': 'for', 'Profissional': 'inf' }[p.type] || 'inf', why: 'Projeto · prazo ' + U.fmtD(p.due) }));
  return out; };
D.summon = o => { const s = S(); if (s.bosses.filter(b => b.status === 'active').length >= 3) { UI.toast('No máximo 3 chefes ativos ao mesmo tempo', 'warn'); return; } const b = Object.assign({ id: U.uid(), created: today(), game: 0, status: 'active', log: [], checks: [] }, o); s.bosses.push(b); D.log(`Chefe invocado: ${b.name}. Prazo ${U.fmtD(b.due)}.`, 'crim'); save(); };
D.attack = (id, heavy) => { const s = S(), b = s.bosses.find(x => x.id === id); if (!b || b.status !== 'active') return 0; const pil = b.pillar || 'cor', res = P[pil].res;
  if (!D.pay({ energy: heavy ? 2 : 1, [res]: heavy ? 20 : 10 })) { UI.toast(`Precisas de ${heavy ? 2 : 1} Determinação e ${heavy ? 20 : 10} de ${P[pil].rn}`, 'warn'); return 0; }
  const ph = D.bossPhase(b), r = 0.8 + Math.random() * .4, dec = D.decree();
  let dmg = Math.round((D.lv(pil) * 4 + (s.b.forja || 0) * 3 + (D.hasRelic('espada') ? 6 : 0) + (s.sk.cor3 ? 6 : 0) + 10) * r * (ph === 2 && !s.sk.inf3 ? .5 : 1) * (dec && dec.id === 'guerra' ? 1.5 : 1) * (heavy ? 1.8 : 1) * D.mor());
  const cap = Math.round(b.max * .4) - (b.game || 0); dmg = Math.max(0, Math.min(dmg, cap));
  b.game = (b.game || 0) + dmg; b.log = [`${U.fmtDS(today())} · golpe de ${dmg}${cap - dmg <= 0 ? ' (o resto do dano tem de vir da vida real)' : ''}`].concat(b.log || []).slice(0, 30);
  D.dayC().atk++; D.weekC().dmg = (D.weekC().dmg || 0) + dmg; save(); return dmg; };
D.gameHit = (id, dmg, src) => { const s = S(), b = s.bosses.find(x => x.id === id); if (!b || b.status !== 'active') return 0; const cap = Math.round(b.max * .4) - (b.game || 0); dmg = Math.max(0, Math.min(Math.round(dmg), cap)); b.game = (b.game || 0) + dmg; b.log = [`${U.fmtDS(today())} · ${src}: ${dmg} de dano${cap - dmg <= 0 ? ' (o resto tem de vir da vida real)' : ''}`].concat(b.log || []).slice(0, 30); D.dayC().atk++; D.weekC().dmg = (D.weekC().dmg || 0) + dmg; save(); return dmg; };
D.bossTick = () => { const s = S(); s.bosses.filter(b => b.status === 'active').forEach(b => {
  if (D.bossHP(b) <= 0) { b.status = 'won'; b.end = today(); s.st.bosses++; D.sp(150); const r = { ouro: 150, pa: 1, xp: { [b.pillar || 'cor']: 200 }, secret: 30 }; D.give(r, 'Chefe derrotado: ' + b.name); if (Math.random() < .5) D.grantRelic('random'); b.reward = r; D.pendingCeremony = { t: 'Chefe derrotado', s: b.name, x: '+150 Ouro · +1 Ascensão · +200 XP' }; }
  else if (b.due < today()) { b.status = 'lost'; b.end = today(); s.st.escaped++; const res = P[b.pillar || 'cor'].res; const loss = Math.round((s.res[res] || 0) * .25); s.res[res] -= loss; s.res.prest = Math.max(0, s.res.prest - 15); D.log(`${b.name} escapou. −${loss} ${P[b.pillar || 'cor'].rn}, −15 Prestígio.`, 'crim'); } });
  s.bosses.filter(b => b.kind === 'exam' && b.status !== 'active' && !b.gloryDone).forEach(b => { const a = OS.get('assessments', b.ref); if (!a || a.grade === '' || a.grade == null) return; const sub = OS.get('subjects', a.subject), tgt = U.num(sub && sub.target) || 15; b.gloryDone = 1; if (U.num(a.grade) >= tgt) { D.give({ ouro: 120, legado: 0, prest: 30, xp: { int: 150 } }, `Glória em ${a.title} (nota ${a.grade})`); } else if (U.num(a.grade) < 10) { s.res.prest = Math.max(0, s.res.prest - 20); D.log(`Ferida: nota ${a.grade} em ${a.title}. −20 Prestígio.`, 'crim'); } });
};

