const LAWS = [['acordar', 'Acordar à hora, sem snooze'], ['redes', 'Zero redes sociais recreativas'], ['estudo', '2 h de estudo profundo', d => mins(d) >= 120], ['treino', 'Treino ou corrida', d => OS.all('workouts').some(w => w.date === d) || OS.all('runs').some(r => r.date === d)], ['leitura', '20 páginas de leitura'], ['oracao', 'Oração / silêncio de manhã'], ['vicios', 'Zero vícios'], ['dormir', 'Dormir à hora, telemóvel fora do quarto']];
D.op = () => S().ops.find(o => o.status === 'active');
D.opDayScore = (o, d) => { const c = (o.log || {})[d] || {}; return LAWS.filter(([k, , auto]) => c[k] || (auto && auto(d))).length / LAWS.length; };
D.opStart = (days, kind = 'elite') => { const s = S(); if (D.op()) return; const lives = 3 + (s.sk.cor5 ? 1 : 0) + (D.hasRelic('tabuas') ? 1 : 0); s.ops.push({ id: U.uid(), kind, days, start: today(), lives, maxLives: lives, log: {}, eval: [], status: 'active' }); D.log(`${kind === 'caverna' ? 'Operação Caverna 40' : 'Operação Elite de ' + days + ' dias'} iniciada. ${lives} vidas.`, 'crim'); save(); };
D.opTick = () => { const s = S(), o = D.op(); if (!o) return; const end = U.addDays(o.start, o.days - 1); const upto = U.addDays(today(), -1);
  U.range(o.start, upto < end ? upto : end).forEach(d => { if ((o.eval || []).includes(d)) return; o.eval = (o.eval || []).concat(d); if (D.opDayScore(o, d) < .75) { o.lives--; D.log(`Operação: dia ${U.diff(d, o.start) + 1} perdido. Restam ${Math.max(0, o.lives)} vidas.`, 'crim'); } });
  if (o.lives <= 0) { o.status = 'failed'; o.end = today(); s.st.lostOps++; const loss = Math.round(s.res.ouro * .3); s.res.ouro -= loss; s.cool = U.addDays(today(), 7); D.log(`Operação falhada. −${loss} Ouro. Nova operação só a partir de ${U.fmtD(s.cool)}.`, 'crim'); D.pendingCeremony = { t: 'Operação falhada', s: 'As vidas acabaram.', x: `−${loss} Ouro · 7 dias de espera`, bad: 1 }; return; }
  if (today() > end) { o.status = 'done'; o.end = today(); s.st.ops++; D.sp(250); const perfect = U.range(o.start, end).filter(d => D.opDayScore(o, d) === 1).length; const r = { ouro: 300 + 20 * o.days + perfect * 10, pa: 2, legado: o.kind === 'caverna' ? 2 : 0, xp: { int: 150, for: 150, cor: 150, inf: 150 }, secret: 100 }; D.give(r, 'Operação concluída'); D.grantRelic(o.kind === 'caverna' ? 'tocha' : 'random'); if (o.lives === o.maxLives) s.ach.sem_macula = s.ach.sem_macula || today(); if (o.kind === 'caverna') s.ach.caverna40 = s.ach.caverna40 || today(); D.pendingCeremony = { t: o.kind === 'caverna' ? 'Saíste da caverna' : 'Operação concluída', s: `${o.days} dias · ${perfect} perfeitos · ${o.lives}/${o.maxLives} vidas`, x: `+${r.ouro} Ouro · +2 Ascensão · relíquia` }; } };

